<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'set_prices');$owner=rxp_target_reseller($ctx);$bot=rxp_bot_info($pdo,$owner);$flash='';$ft='ok';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$bot)rxp_abort(409,'ربات اختصاصی وجود ندارد.');$s=json_decode((string)$bot['setting'],true)?:[];$ints=['minpricetime','pricetime','minpricevolume','pricevolume'];$valid=true;foreach($ints as $k){$v=(int)($_POST[$k]??0);if($v<0||$v>100000000){$valid=false;$flash='قیمت نامعتبر است.';$ft='err';break;}$s[$k]=$v;}if($valid){$s['support_username']=mb_substr(trim((string)($_POST['support_username']??'')),0,100);$s['channel']=mb_substr(trim((string)($_POST['channel']??'')),0,100);$s['show_product']=isset($_POST['show_product']);$pdo->prepare('UPDATE botsaz SET setting=? WHERE id_user=?')->execute([json_encode($s,JSON_UNESCAPED_UNICODE),$owner]);rxp_audit($pdo,$ctx,'bot.settings',$owner);$bot['setting']=json_encode($s);$flash='تنظیمات ربات ذخیره شد.';}}$s=$bot?(json_decode((string)$bot['setting'],true)?:[]):[];rxp_layout_start($ctx,'تنظیمات ربات','bot_settings.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">تنظیمات ربات اختصاصی</h1><?php if($ctx['role']==='super'):?><div class="rxp-card"><form method="get"><select name="owner" onchange="this.form.submit()"><?php foreach($ctx['scope_ids'] as $id):?><option value="<?=$id?>" <?=$owner===$id?'selected':''?>>نماینده #<?=$id?></option><?php endforeach;?></select></form></div><?php endif;?><?php if(!$bot):?><div class="rxp-flash err">این نماینده ربات اختصاصی ندارد.</div><?php else:?><div class="rxp-card"><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><div class="rxp-grid"><?php foreach(['minpricetime'=>'حداقل قیمت روز','pricetime'=>'قیمت هر روز','minpricevolume'=>'حداقل قیمت گیگ','pricevolume'=>'قیمت هر گیگ'] as $k=>$l):?><div class="rxp-field"><label><?=$l?></label><input type="number" name="<?=$k?>" min="0" value="<?=(int)($s[$k]??0)?>"></div><?php endforeach;?></div><div class="rxp-form"><div class="rxp-field"><label>آیدی پشتیبانی</label><input name="support_username" value="<?=rxp_h($s['support_username']??'')?>"></div><div class="rxp-field"><label>کانال اجباری بدون @</label><input name="channel" value="<?=rxp_h($s['channel']??'')?>"></div><label class="rxp-muted"><input type="checkbox" name="show_product" <?=!empty($s['show_product'])?'checked':''?>> نمایش محصولات</label><button class="rxp-btn">ذخیره</button></div></form></div><?php endif;?><?php rxp_layout_end();
